IF DB_ID('credit_analysis') IS NULL
    CREATE DATABASE credit_analysis;
GO

USE credit_analysis;
GO

DROP TABLE IF EXISTS credit_data;
GO

CREATE TABLE credit_data (
    Customer_ID INT PRIMARY KEY,
    Customer_Name VARCHAR(100),
    DOB DATE,
    Age INT,
    Age_Group VARCHAR(20),
    Marital_Status VARCHAR(30),
    Education VARCHAR(50),
    Occupation VARCHAR(50),
    Employment_Type VARCHAR(50),
    City VARCHAR(50),
    State VARCHAR(50),
    Annual_Income DECIMAL(15,2),
    Income_Band VARCHAR(20),
    Credit_Score INT,
    Credit_Score_Band VARCHAR(20),
    Loan_Amount DECIMAL(15,2),
    Loan_to_Income_Ratio DECIMAL(10,4),
    Loan_Type VARCHAR(50),
    Loan_Tenure_Months INT,
    Interest_Rate DECIMAL(6,2),
    Debt_to_Income_Ratio DECIMAL(8,4),
    Monthly_Debt DECIMAL(15,2),
    Loan_Status VARCHAR(30),
    Risk_Category VARCHAR(30),
    Default_Probability DECIMAL(8,4),
    Utilization_Ratio DECIMAL(8,4),
    Existing_Loans INT,
    Late_Payments INT,
    Application_Channel VARCHAR(30),
    Application_Date DATE
);











select * from credit_data;

-- Total customers

SELECT COUNT(*) AS total_customers
FROM credit_data;

-- Average credit score

SELECT AVG(credit_score) AS avg_credit_score
FROM credit_data;

-- Average income

SELECT AVG(annual_income) AS avg_income
FROM credit_data;

-- Total loan amount

SELECT SUM(loan_amount) AS total_loan_amount
FROM credit_data;

-- Loan Status Analysis

SELECT 
    loan_status,
    COUNT(*) AS applications
FROM credit_data
GROUP BY loan_status
ORDER BY applications DESC;

-- Risk Category Analysis

SELECT
    risk_category,
    COUNT(*) AS customers,
    AVG(credit_score) AS avg_credit_score,
    AVG(default_probability) AS avg_default_probability
FROM credit_data
GROUP BY risk_category
ORDER BY avg_default_probability DESC;

-- Loan Type Analysis

SELECT
    loan_type,
    COUNT(*) AS applications,
    SUM(loan_amount) AS total_loan,
    AVG(interest_rate) AS avg_interest_rate
FROM credit_data
GROUP BY loan_type
ORDER BY total_loan DESC;

-- State-Wise Analysis

SELECT
    state,
    COUNT(*) AS customers,
    SUM(loan_amount) AS total_loan,
    AVG(credit_score) AS avg_credit_score
FROM credit_data
GROUP BY state
ORDER BY total_loan DESC;

-- Top 10 Customers by Loan Amount

SELECT TOP 10
    customer_id,
    customer_name,
    loan_amount,
    credit_score,
    risk_category
FROM credit_data
ORDER BY loan_amount DESC;

-- High-Risk Customers

SELECT
    customer_id,
    customer_name,
    credit_score,
    annual_income,
    loan_amount,
    debt_to_income_ratio,
    default_probability
FROM credit_data
WHERE risk_category IN ('High','Very High')
ORDER BY default_probability DESC;

-- Customers With Poor Credit Score

SELECT *
FROM credit_data
WHERE credit_score < 580
ORDER BY credit_score;

-- Customers With High DTI

SELECT
    customer_id,
    customer_name,
    annual_income,
    monthly_debt,
    debt_to_income_ratio
FROM credit_data
WHERE debt_to_income_ratio > 0.50
ORDER BY debt_to_income_ratio DESC;

-- Approval Rate

SELECT
    COUNT(CASE WHEN loan_status = 'Approved' THEN 1 END) * 100.0
    / COUNT(*) AS approval_rate
FROM credit_data;

-- Rejection Rate

SELECT
    COUNT(CASE WHEN loan_status = 'Rejected' THEN 1 END) * 100.0
    / COUNT(*) AS rejection_rate
FROM credit_data;

-- Average Credit Score by Loan Type

SELECT
    loan_type,
    ROUND(AVG(credit_score),2) AS avg_credit_score
FROM credit_data
GROUP BY loan_type
ORDER BY avg_credit_score DESC;

-- Late Payments Analysis

SELECT
    risk_category,
    AVG(late_payments) AS avg_late_payments,
    MAX(late_payments) AS maximum_late_payments
FROM credit_data
GROUP BY risk_category;

-- High-Risk + High DTI

SELECT
    customer_id,
    customer_name,
    credit_score,
    debt_to_income_ratio,
    default_probability,
    risk_category
FROM credit_data
WHERE debt_to_income_ratio > 0.50
AND risk_category IN ('High','Very High')
ORDER BY default_probability DESC;

-- Find each customer's ranking by loan amount:

SELECT
    customer_id,
    customer_name,
    loan_amount,
    RANK() OVER (
        ORDER BY loan_amount DESC
    ) AS loan_rank
FROM credit_data;

-- Monthly Applications

SELECT
    YEAR(application_date) AS year,
    MONTH(application_date) AS month,
    COUNT(*) AS applications
FROM credit_data
GROUP BY
    YEAR(application_date),
    MONTH(application_date)
ORDER BY year, month;

